import { useEffect, useState } from "react";
import API from "../services/api";
import "./Historial.css";

function HistorialPedidos() {
  const [pedidos, setPedidos] = useState([]);
  const [error, setError] = useState(null);

  // ✅ Parseo seguro del usuario
  const usuario = (() => {
    try {
      return JSON.parse(localStorage.getItem("usuario"));
    } catch {
      return null;
    }
  })();

  useEffect(() => {
    if (!usuario?.id_usuario) {
      setError("No se encontró el usuario en sesión.");
      return;
    }
    cargarPedidos();
  }, []);

  const cargarPedidos = async () => {
    try {
      const res = await API.get(`/historial/${usuario.id_usuario}`);

      // ✅ Garantiza que siempre sea array
      const data = Array.isArray(res.data) ? res.data : [];
      setPedidos(data);

      // 👇 Agrega esto temporalmente para ver qué llega del backend
      console.log("Respuesta del backend:", res.data);

    } catch (error) {
      console.error("Error al cargar pedidos:", error);
      setError("Error al cargar el historial.");
    }
  };

  if (error) return <p style={{ color: "red" }}>{error}</p>;

  return (
    <div className="historial-container">
      <h2>Historial de Compras</h2>
      <h3 className="subtitulo">Tus pedidos</h3>

      {pedidos.length === 0 ? (
        <p>No tienes compras aún</p>
      ) : (
        pedidos.map((p, index) => (
          // ✅ Key con índice para evitar colisiones por id_producto repetido
          <div className="pedido-card" key={`${p.id_producto}-${index}`}>
            <div className="pedido-header">
              <h3>Pedido #{p.id_producto}</h3>
              <span className="estado pendiente">Vendido</span>
            </div>
            <p className="fecha">
              {new Date(p.fecha_salida).toLocaleString()}
            </p>
            <hr />
            <h2 className="total">Total: ${p.valor}</h2>
          </div>
        ))
      )}
    </div>
  );
}

export default HistorialPedidos;
